credentials.","mechanics":{"rarity":"Common"}},{"id":"demo62-6-climbing-hook-and-fine-rope","name":"Climbing hook and fine rope","kind":"tool","qty":1,"quantity":1,"location":"backpack","slot":"","description":"Portable climbing supplies.","mechanics":{"rarity":"Common"}},{"id":"demo62-6-caltrops-in-a-padded-tin","name":"Caltrops in a padded tin","kind":"consumable","qty":12,"quantity":12,"location":"backpack","slot":"","description":"Mundane defensive caltrops.","mechanics":{"rarity":"Common"}},{"id":"demo62-6-street-chalk-sticks","name":"Street chalk sticks","kind":"item","qty":3,"quantity":3,"location":"backpack","slot":"","description":"Discreet route markings.","mechanics":{"rarity":"Common"}},{"id":"demo62-6-common-disguise-kit","name":"Common disguise kit","kind":"tool","qty":1,"quantity":1,"location":"backpack","slot":"","description":"Ordinary disguise materials.","mechanics":{"rarity":"Common"}},{"id":"demo62-6-pocket-mirror","name":"Pocket mirror","kind":"item","qty":1,"quantity":1,"location":"backpack","slot":"","description":"A mirror for checking a corner.","mechanics":{"rarity":"Common"}},{"id":"demo62-6-old-public-bounty-notices","name":"Old public bounty notices","kind":"item","qty":4,"quantity":4,"location":"backpack","slot":"","description":"Collected public notices.","mechanics":{"rarity":"Common"}}],"feats":[{"name":"Borrowed Shadow","short_description":"Can blend into the movement of a busy street.","rules_text":"In crowds, describe a plausible route through foot traffic before an appropriate Stealth or Deception check. No invisibility.","prerequisites":"","action_type":"passive","uses_per_rest":0,"recovery":"manual","minimum_level":1,"rarity":"Custom","state":"ready"},{"name":"Slip the Net","short_description":"Familiarity with loose restraints.","rules_text":"Bonus action, twice per short rest: attempt to wriggle free of an unsecured grip or cord, subject to a check; secure shackles remain secure.","prerequisites":"","action_type":"bonus action","uses_per_rest":2,"recovery":"short","minimum_level":4,"rarity":"Custom","state":"ready"}],"purse":[{"denomination":"human-civics-100-civics","quantity":1},{"denomination":"human-civics-50-civics","quantity":2},{"denomination":"human-civics-5-civics","quantity":5},{"denomination":"guild-seals-copper-seal","quantity":16}],"enhance":{"demo-balanced-shortblade":{"rarity":"Uncommon"},"demo-smoke-coloured-cloak":{"rarity":"Rare"}},"removeInventoryIds":["demo-copper-coins"],"training":{"tools":["thieves-tools","disguise-kit","terr-game-fifth-hand"],"languages":["common","thieves-cant"]},"vault_picks":["demo62-6-night-market-hood","demo62-6-climbing-hook-and-fine-rope"]},{"slot":7,"name":"Aster Vaelith","items":[{"id":"demo62-7-archive-travel-hood","name":"Archive travel hood","kind":"helmet","qty":1,"quantity":1,"location":"equipped","slot":"head","description":"Soft hood that leaves his wings unobstructed.","mechanics":{"rarity":"Common"}},{"id":"demo62-7-inkkeeper-gloves","name":"Inkkeeper gloves","kind":"trinket","qty":1,"quantity":1,"location":"equipped","slot":"gloves","description":"Manuscript-safe working gloves.","mechanics":{"rarity":"Common"}},{"id":"demo62-7-scholar-s-split-trousers","name":"Scholar's split trousers","kind":"armour","qty":1,"quantity":1,"location":"equipped","slot":"legs","description":"Trousers with small notebook pockets.","mechanics":{"rarity":"Common"}},{"id":"demo62-7-quiet-corridor-shoes","name":"Quiet corridor shoes","kind":"armour","qty":1,"quantity":1,"location":"equipped","slot":"feet","description":"Soft shoes for late-night research.","mechanics":{"rarity":"Common"}},{"id":"demo62-7-wing-safe-library-mantle","name":"Wing-safe library mantle","kind":"trinket","qty":1,"quantity":1,"location":"equipped","slot":"cloak","description":"Split-back cloak cut for his waist-rooted wings.","mechanics":{"rarity":"Common"}},{"id":"demo62-7-index-keeper-s-pendant","name":"Index-keeper's pendant","kind":"trinket","qty":1,"quantity":1,"location":"equipped","slot":"neck","description":"Blank catalogue-index pendant.","mechanics":{"rarity":"Common"}},{"id":"demo62-7-marginlight-ring","name":"Marginlight ring","kind":"trinket","qty":1,"quantity":1,"location":"equipped","slot":"ring1","description":"Gentle illumination for reading.","mechanics":{"rarity":"Uncommon","attunement":true,"attuned":true,"max_charges":3,"charges":3,"recovery":"long","charge_cost":1,"resource_tracker":true,"features":"One charge illuminates a nearby page softly. Does not reveal secret text."}},{"id":"demo62-7-folding-aether-quill","name":"Folding aether quill","kind":"tool","qty":1,"quantity":1,"location":"equipped","slot":"focus","description":"A small collapsible writing focus.","mechanics":{"rarity":"Rare","max_charges":2,"charges":2,"recovery":"dawn","charge_cost":1,"resource_tracker":true,"features":"One charge draws a brief non-permanent diagram annotation; no independent spell effects."}},{"id":"demo62-7-reagent-index-case","name":"Reagent index case","kind":"tool","qty":1,"quantity":1,"location":"equipped","slot":"accessory2","description":"Indexed reagent sleeves.","mechanics":{"rarity":"Common"}},{"id":"demo62-7-pocket-concordance-sheets","name":"Pocket concordance sheets","kind":"item","qty":6,"quantity":6,"location":"backpack","slot":"","description":"Duplicates of ordinary library references.","mechanics":{"rarity":"Common"}},{"id":"demo62-7-blank-diagram-vellum","name":"Blank diagram vellum","kind":"item","qty":8,"quantity":8,"location":"backpack","slot":"","description":"Vellum for aether diagrams.","mechanics":{"rarity":"Common"}},{"id":"demo62-7-rainproof-ink-vials","name":"Rainproof ink vials","kind":"consumable","qty":3,"quantity":3,"location":"backpack","slot":"","description":"Water-resistant ordinary ink.","mechanics":{"rarity":"Common"}},{"id":"demo62-7-foldaway-book-stand","name":"Foldaway book stand","kind":"tool","qty":1,"quantity":1,"location":"backpack","slot":"","description":"Lightweight travel stand.","mechanics":{"rarity":"Common"}},{"id":"demo62-7-emergency-warmth-wrap","name":"Emergency warmth wrap","kind":"item","qty":1,"quantity":1,"location":"backpack","slot":"","description":"A blanket for companions.","mechanics":{"rarity":"Common"}},{"id":"demo62-7-plain-sealing-wax","name":"Plain sealing wax","kind":"consumable","qty":4,"quantity":4,"location":"backpack","slot":"","description":"Wax for marking mundane copies.","mechanics":{"rarity":"Common"}},{"id":"demo62-7-unsent-letters","name":"Unsent letters","kind":"item","qty":2,"quantity":2,"location":"backpack","slot":"","description":"Sealed private correspondence.","mechanics":{"rarity":"Common"}}],"feats":[{"name":"Cataloguer's Eye","short_description":"Connects references without claiming unknown secrets.","rules_text":"When comparing texts you have already read, request an ordinary cross-reference from the DM. Cannot access sealed archives or hidden knowledge.","prerequisites":"","action_type":"passive","uses_per_rest":0,"recovery":"manual","minimum_level":1,"rarity":"Custom","state":"ready"},{"name":"Margin of Safety","short_description":"Notices mundane hazards before companions stumble into them.","rules_text":"Reaction, once per long rest: alert an ally in sight to a clearly visible environmental hazard before the DM resolves it.","prerequisites":"","action_type":"reaction","uses_per_rest":1,"recovery":"long","minimum_level":3,"rarity":"Custom","state":"ready"}],"purse":[{"denomination":"fl-gel-currents-100-current","quantity":1},{"denomination":"fl-gel-currents-50-current","quantity":2},{"denomination":"fl-gel-currents-5-current","quantity":5},{"denomination":"guild-seals-copper-seal","quantity":3}],"enhance":{"demo-grand-library-field-notebook":{"rarity":"Rare","charges":3},"demo-ink-stained-satchel":{"rarity":"Uncommon"}},"removeInventoryIds":[],"training":{"tools":["archive-conservator-s-tools","calligrapher-s-supplies","aetheric-calibration-instruments"],"languages":["common","fl-gel","elven"]},"vault_picks":["demo62-7-marginlight-ring","demo62-7-foldaway-book-stand"]}]}$fixture$::jsonb;
  demo_cid uuid; curator uuid; hero jsonb; target_demo_id uuid;
  current_inv jsonb; preserved_inv jsonb; extras jsonb; new_inv jsonb;
  equipment jsonb; feat jsonb; coin jsonb; target_feat_id uuid;
  property_name text; property_data jsonb; old_quantity bigint; new_quantity bigint;
  rate bigint; changes bigint; active_count integer; items_count integer;
  expected integer := jsonb_array_length(kit->'characters');
begin
  perform pg_advisory_xact_lock(hashtextextended('terravale_demo_v262_curated_showcase',0));
  if expected<>7 then raise exception 'Expected seven demo character specifications';end if;
  select c.campaign_id into demo_cid
  from public.terravale_demo_curator_credits d join public.characters c on c.id=d.character_id
  join public.terravale_system_campaigns sc on sc.campaign_id=c.campaign_id and sc.kind='wayfarers-demo'
  group by c.campaign_id having count(*)=7
    and bool_and(c.owner_id is null and c.status='approved' and c.sheet_visible_to_party);
  if demo_cid is null then
   raise exception 'Missing the seven approved ownerless curated demo characters';end if;
  select owner_id into curator from public.campaigns where id=demo_cid;
  if curator is null or not exists(
   select 1 from auth.identities where user_id=curator and provider='discord'
  ) then raise exception 'Verified demo campaign curator unavailable';end if;
  -- Supplies the correct actor identity to existing audit triggers.
  perform set_config('request.jwt.claim.sub',curator::text,true);
  for hero in select value from jsonb_array_elements(kit->'characters') loop
    select c.id into target_demo_id
    from public.terravale_demo_curator_credits d
    join public.characters c on c.id=d.character_id
    where d.template_slot=(hero->>'slot')::integer
      and c.campaign_id=demo_cid and c.name=hero->>'name'
      and c.owner_id is null and c.status='approved'
      and c.sheet_visible_to_party
      and c.approved_build #>> '{character,demoCurator}'='aster'
    for update of c;
    if target_demo_id is null then raise exception 'Missing curated character slot %',hero->>'slot';end if;
    select inventory into current_inv from public.character_state
     where character_id=target_demo_id for update;
    if current_inv is null or jsonb_typeof(current_inv)<>'array'
    then raise exception 'Invalid inventory on demo character %',hero->>'name';end if;

    select coalesce(jsonb_agg(e.value order by e.ordinality),'[]'::jsonb)
      into preserved_inv
      from jsonb_array_elements(current_inv) with ordinality e(value,ordinality)
      where coalesce(e.value->>'id','') not like 'demo62-%'
       and not exists(select 1 from jsonb_array_elements_text(
         coalesce(hero->'removeInventoryIds','[]'::jsonb)) x(value)
         where x.value=e.value->>'id');
    select coalesce(jsonb_agg(e.value-'mechanics' order by e.ordinality),'[]'::jsonb)
      into extras from jsonb_array_elements(hero->'items') with ordinality e(value,ordinality);
    new_inv:=preserved_inv||extras;
    select count(*) into items_count from jsonb_array_elements(new_inv);
    if items_count<15 or items_count>80 or (
      select count(distinct e.value->>'id') from jsonb_array_elements(new_inv) e(value)
    )<>items_count then raise exception 'Missing or duplicate demo item IDs on %',hero->>'name';end if;
    if (select count(*) from jsonb_array_elements(new_inv) e(value)
        where e.value->>'location'='equipped')
      <> (select count(distinct e.value->>'slot') from jsonb_array_elements(new_inv) e(value)
        where e.value->>'location'='equipped')
    then raise exception 'Conflicting equipped slot for %',hero->>'name';end if;
    update public.character_state
      set inventory=new_inv
      where character_id=target_demo_id and inventory is distinct from new_inv;

    -- Every visible item has rarity; preserve previously authored mechanics.
    for equipment in select value from jsonb_array_elements(preserved_inv) loop
      insert into public.character_item_properties(character_id,item_id,properties)
      values(target_demo_id,equipment->>'id',jsonb_build_object('rarity','Common'))
      on conflict do nothing;
    end loop;
    for equipment in select value from jsonb_array_elements(hero->'items') loop
      insert into public.character_item_properties(character_id,item_id,properties)
      values(target_demo_id,equipment->>'id',equipment->'mechanics')
      on conflict (character_id,item_id) do update set
       properties=excluded.properties,updated_at=now();
    end loop;
    for property_name,property_data in select key,value from jsonb_each(hero->'enhance') loop
      if not exists(select 1 from jsonb_array_elements(new_inv) e(value)
        where e.value->>'id'=property_name) then
        raise exception 'Cannot enhance absent item % on %',property_name,hero->>'name';
      end if;
      insert into public.character_item_properties(character_id,item_id,properties)
      values(target_demo_id,property_name,property_data)
      on conflict (character_id,item_id) do update set
       properties=public.character_item_properties.properties || excluded.properties,
       updated_at=now();
    end loop;
    -- Showcase class-appropriate languages and tool/instrument training.
    -- Only these seven approved, ownerless demos are touched.
    update public.terravale_character_proficiencies set
      tools=(select jsonb_agg(jsonb_build_object('id',t.value))
             from jsonb_array_elements_text(hero->'training'->'tools') t(value)),
      languages=(select jsonb_agg(jsonb_build_object('id',l.value))
             from jsonb_array_elements_text(hero->'training'->'languages') l(value)),
      submitted=true,updated_at=now()
      where character_id=target_demo_id;

    -- Two reusable prepared Vault entries per character, demonstrating the
    -- DM inventory workflow without duplicating its item editor.
    for equipment in select e.value
      from jsonb_array_elements(hero->'items') e(value)
      where e.value->>'id' in (
        select x.value from jsonb_array_elements_text(hero->'vault_picks') x(value)
      )
    loop
      insert into public.terravale_dm_vault_items(
        id,owner_user_id,campaign_id,item_data,mechanics
      ) values (
        md5('v262-demo-vault:' || (equipment->>'id'))::uuid,
        curator,demo_cid,
        equipment-'mechanics'-'location'-'slot'-'id',
        equipment->'mechanics'
      ) on conflict (id) do update set
        item_data=excluded.item_data,mechanics=excluded.mechanics,
        updated_at=now();
    end loop;

    -- Independent DM-authored examples, not modifications to any class,
    -- ancestry, Bloodforger or lore rules.
    for feat in select value from jsonb_array_elements(hero->'feats') loop
      if (feat->>'minimum_level')::int > 
        (select (c.approved_build->>'level')::int from public.characters c where c.id=target_demo_id)
      then raise exception 'Feat exceeds the demo level: %',feat->>'name';end if;
      select f.id into target_feat_id from public.terravale_dm_custom_feats f
       where f.campaign_id=demo_cid and f.name=feat->>'name' limit 1;
      if target_feat_id is null then
        insert into public.terravale_dm_custom_feats(
         campaign_id,created_by,name,short_description,prerequisites,rules_text,
         action_type,uses_per_rest,recovery,minimum_level,rarity,state
        ) values(
         demo_cid,curator,feat->>'name',feat->>'short_description',
         feat->>'prerequisites',feat->>'rules_text',feat->>'action_type',
         (feat->>'uses_per_rest')::integer,feat->>'recovery',
         (feat->>'minimum_level')::integer,feat->>'rarity','ready'
        ) returning id into target_feat_id;
      else
        update public.terravale_dm_custom_feats set
          short_description=feat->>'short_description',
          prerequisites=feat->>'prerequisites',rules_text=feat->>'rules_text',
          action_type=feat->>'action_type',
          uses_per_rest=(feat->>'uses_per_rest')::integer,
          recovery=feat->>'recovery',
          minimum_level=(feat->>'minimum_level')::integer,
          rarity=feat->>'rarity',state='ready',updated_at=now()
        where id=target_feat_id;
      end if;
      if not exists(select 1 from public.terravale_character_custom_feats
         where character_id=target_demo_id and feat_id=target_feat_id and status='active')
      then
        insert into public.terravale_character_custom_feats(
          feat_id,character_id,campaign_id,granted_by,grant_note
        ) values(target_feat_id,target_demo_id,demo_cid,curator,
         'Aster-curated demo showcase; illustrative DM-awarded ability');
      end if;
    end loop;

    -- Monetary opening balances are actual denomination holdings, not
    -- UI-only mock values. Record each change in the existing wallet ledger.
    for coin in select value from jsonb_array_elements(hero->'purse') loop
      select gc_value into rate from public.terravale_currency_denominations
       where id=coin->>'denomination' and enabled=true;
      if rate is null then raise exception 'Unregistered denomination %',coin->>'denomination';end if;
      new_quantity:=(coin->>'quantity')::bigint;
      if new_quantity<0 or new_quantity>1000000 then
        raise exception 'Invalid demo wallet quantity';end if;
      select quantity into old_quantity from public.terravale_character_wallet
       where character_id=target_demo_id and denomination_id=coin->>'denomination'
       for update;
      old_quantity:=coalesce(old_quantity,0);
      changes:=new_quantity-old_quantity;
      if changes<>0 then
        insert into public.terravale_character_wallet(character_id,denomination_id,quantity)
        values(target_demo_id,coin->>'denomination',new_quantity)
        on conflict (character_id,denomination_id) do update set
          quantity=excluded.quantity,updated_at=now();
        insert into public.terravale_wallet_ledger(
         character_id,actor_user_id,denomination_id,delta,balance_after,
         rate_gc_snapshot,operation,note
        ) values(
         target_demo_id,curator,coin->>'denomination',changes,new_quantity,
         rate,case when changes>0 then 'dm_issue' else 'dm_remove' end,
         'V2.62 Aster-curated demo opening purse'
        );
      end if;
    end loop;
    select count(*) into active_count from public.terravale_character_custom_feats
     where character_id=target_demo_id and status='active';
    if active_count<2 then raise exception 'Demo custom feats missing for %',hero->>'name';end if;
    raise notice 'Curated demo %: % items, % active custom feats',hero->>'name',items_count,active_count;
  end loop;
end
$v262$;
